-- FitFlow Pro, atualização 02: catálogo com os 50 exercícios. Rode uma vez no SQL Editor do Supabase.
on conflict (id) do update set
  name = excluded.name,
  muscle_group = excluded.muscle_group,
  equipment = excluded.equipment,
  instructions = excluded.instructions;

-- Exercícios que saíram do catálogo (mantidos se já houver séries registradas neles).
delete from public.exercises e
where e.id not in ('supino-reto', 'supino-inclinado', 'crucifixo', 'crossover', 'flexao', 'peck-deck', 'puxada-frontal', 'barra-fixa', 'remada-curvada', 'remada-unilateral', 'remada-baixa', 'pulldown', 'levantamento-terra', 'desenvolvimento-halteres', 'desenvolvimento-militar', 'elevacao-lateral', 'elevacao-frontal', 'crucifixo-inverso', 'encolhimento', 'rosca-direta', 'rosca-alternada', 'rosca-martelo', 'rosca-scott', 'rosca-concentrada', 'triceps-polia', 'triceps-testa', 'triceps-frances', 'mergulho-banco', 'mergulho', 'agachamento-livre', 'leg-press', 'cadeira-extensora', 'afundo', 'agachamento-bulgaro', 'agachamento-hack', 'elevacao-pelvica', 'cadeira-abdutora', 'cadeira-adutora', 'mesa-flexora', 'cadeira-flexora', 'stiff', 'panturrilha-em-pe', 'panturrilha-sentado', 'abdominal-supra', 'elevacao-pernas', 'abdominal-infra', 'prancha', 'abdominal-obliquo', 'abdominal-polia', 'extensao-lombar')
  and not exists (select 1 from public.workout_logs l where l.exercise_id = e.id);
